class Solution {
  private static long dpBest(int[] a, long[] d, int from, int to) {
    long NEG = Long.MIN_VALUE / 4;
    long s1 = NEG, s2 = NEG, s3 = NEG, best = NEG;
    for (int i = from; i <= to; i++) {
      long x = a[i];
      long n1 = Math.max(s1, 0) + x;
      long n2 = Math.max(Math.max(s1, s2), 0) + x + d[i];
      long n3 = Math.max(s2, s3) + x;
      s1 = n1;
      s2 = n2;
      s3 = n3;
      best = Math.max(best, Math.max(n1, Math.max(n2, n3)));
    }
    return best;
  }

  public long maxSubarraySum(int[] nums, int k) {
    int n = nums.length;
    long total = 0;
    for (int v : nums) total += v;
    long[][] gains = new long[2][n];
    for (int i = 0; i < n; i++) {
      gains[0][i] = (long) nums[i] * k - nums[i];
      gains[1][i] = nums[i] / k - nums[i];
    }
    long best = Long.MIN_VALUE;
    for (int op = 0; op < 2; op++) {
      long cur = Long.MIN_VALUE / 4, bestGain = Long.MIN_VALUE;
      for (int i = 0; i < n; i++) {
        cur = Math.max(cur, 0) + gains[op][i];
        bestGain = Math.max(bestGain, cur);
      }
      best = Math.max(best, total + bestGain);
      if (n >= 2) {
        best = Math.max(best, dpBest(nums, gains[op], 0, n - 2));
        best = Math.max(best, dpBest(nums, gains[op], 1, n - 1));
      }
    }
    return best;
  }
}
